∀ {u : Real}
  {motive : (a : List.{0} (Prod.{0, 0} Real Real)) → (a_1 : Real) → Research.CholeskySolve.DotTrace u a a_1 → Prop},
  Research.CholeskySolve.DotTrace.below ⋯

∀ {u : Real}
  {motive : (a : List.{0} (Prod.{0, 0} Real Real)) → (a_1 : Real) → Research.CholeskySolve.DotTrace u a a_1 → Prop}
  (a b p : Real) (hp : Research.CholeskySolve.Rounded u (HMul.hMul.{0, 0, 0} a b) p),
  Research.CholeskySolve.DotTrace.below ⋯

∀ {u : Real}
  {motive : (a : List.{0} (Prod.{0, 0} Real Real)) → (a_1 : Real) → Research.CholeskySolve.DotTrace u a a_1 → Prop}
  (xs : List.{0} (Prod.{0, 0} Real Real)) (a b s p t : Real) (hne : Ne.{1} xs List.nil.{0})
  (hs : Research.CholeskySolve.DotTrace u xs s) (hp : Research.CholeskySolve.Rounded u (HMul.hMul.{0, 0, 0} a b) p)
  (ht : Research.CholeskySolve.Rounded u (HAdd.hAdd.{0, 0, 0} s p) t),
  Research.CholeskySolve.DotTrace.below hs → motive xs s hs → Research.CholeskySolve.DotTrace.below ⋯

∀ {u : Real}
  {motive : (a : List.{0} (Prod.{0, 0} Real Real)) → (a_1 : Real) → Research.CholeskySolve.DotTrace u a a_1 → Prop}
  {a : List.{0} (Prod.{0, 0} Real Real)} {a_1 : Real} (t : Research.CholeskySolve.DotTrace u a a_1),
  (∀ (a : List.{0} (Prod.{0, 0} Real Real)) (a_2 : Real) (t : Research.CholeskySolve.DotTrace u a a_2),
      Research.CholeskySolve.DotTrace.below t → motive a a_2 t) →
    motive a a_1 t

∀ {n : Nat} {u : Real} {A : Matrix.{0, 0, 0} (Fin n) (Fin n) Real} {b : Fin n → Real}
  {R : Matrix.{0, 0, 0} (Fin n) (Fin n) Real} {y x : Fin n → Real},
  Research.CholeskySolve.SolveTrace u A b R y x → Research.CholeskySolve.BackwardTrace u R y x

∀ {n : Nat} {u : Real} {A : Matrix.{0, 0, 0} (Fin n) (Fin n) Real} {b : Fin n → Real}
  {R : Matrix.{0, 0, 0} (Fin n) (Fin n) Real} {y x : Fin n → Real},
  Research.CholeskySolve.SolveTrace u A b R y x → Research.CholeskySolve.FactorTrace u A R

∀ {n : Nat} (p : Fin n → Prop) [inst : DecidablePred.{1} p] (a b : Fin n → Real),
  LE.le.{0}
    (List.length.{0}
      (List.map.{0, 0} (fun k => Prod.mk.{0, 0} (a k) (b k))
        (List.filter.{0} (fun k => Decidable.decide (p k)) (List.finRange n))))
    n
